begin;
select set_config('vq.test.a',(select user_id::text from public.community_profiles where visible and avatar is not null and username !~* '^Member_[a-f0-9]{8}$' order by user_id limit 1),true);
select set_config('vq.test.b',(select user_id::text from public.community_profiles where visible and avatar is not null and username !~* '^Member_[a-f0-9]{8}$' order by user_id offset 1 limit 1),true);
select set_config('request.jwt.claim.sub',current_setting('vq.test.b'),true);
set local role authenticated;
do $$declare p uuid;bad boolean:=false;r uuid;begin
 insert into public.community_posts(user_id,sport,kind,title,body) values(auth.uid(),'nfl','talk','ROLLBACK SAFETY','Safe sports discussion') returning id into p;
 perform set_config('request.jwt.claim.sub',current_setting('vq.test.a'),true);
 insert into public.member_blocks(user_id,target_user_id,label) values(auth.uid(),current_setting('vq.test.b')::uuid,'Test member');
 if exists(select 1 from public.community_posts where id=p) then raise exception 'Block failed';end if;
 begin insert into public.community_reactions(post_id,user_id) values(p,auth.uid());exception when raise_exception then bad=true;end;
 if not bad then raise exception 'Blocked interaction accepted';end if;
 r=public.request_account_deletion();if public.request_account_deletion()<>r then raise exception 'Dedupe failed';end if;
 perform set_config('request.jwt.claim.sub',current_setting('vq.test.b'),true);
 if exists(select 1 from public.member_blocks where user_id=current_setting('vq.test.a')::uuid) then raise exception 'Block privacy failed';end if;
 if exists(select 1 from public.account_deletion_requests where id=r) then raise exception 'Request privacy failed';end if;
 bad=false;begin perform public.restrict_community_member(current_setting('vq.test.a')::uuid,'Unauthorized');exception when raise_exception then bad=true;end;
 if not bad then raise exception 'Admin authorization failed';end if;
 perform set_config('request.jwt.claim.sub',current_setting('vq.test.a'),true);
 delete from public.member_blocks where target_user_id=current_setting('vq.test.b')::uuid;
 if not exists(select 1 from public.community_posts where id=p) then raise exception 'Unblock failed';end if;
 bad=false;begin insert into public.community_posts(user_id,sport,kind,title,body) values(auth.uid(),'nfl','talk','guaranteed profit','Must be filtered');exception when raise_exception then bad=true;end;
 if not bad then raise exception 'Filter failed';end if;
 perform public.cancel_account_deletion_request();if not exists(select 1 from public.account_deletion_requests where id=r and status='canceled') then raise exception 'Cancel failed';end if;
end $$;
rollback;
